import {
  useMemo,
  useState,
} from "react";

import {
  Box,
  Button,
  ButtonGroup,
  Divider,
  Stack,
  Typography,
} from "@mui/material";

import {
  AirRounded,
  CloudRounded,
  OpacityRounded,
  ThermostatRounded,
  UmbrellaRounded,
  WbSunnyRounded,
  WaterDropRounded,
} from "@mui/icons-material";

import {
  useWeatherOutlook,
  useWeatherSignals,
  useWeatherSummary,
} from "../hooks/useWeather";

import {
  WeatherOutlookDay,
} from "../types/weather.types";


interface WeatherIntelligenceProps {
  entityId: string;
}


type WeatherView =
  | "current"
  | "7"
  | "30";


const WeatherIntelligence = ({
  entityId,
}: WeatherIntelligenceProps) => {
  const [
    view,
    setView,
  ] = useState<WeatherView>(
    "current"
  );


  const days =
    view === "30"
      ? 30
      : 7;


  const {
    data: current,
    isLoading:
      currentLoading,
    isError:
      currentError,
  } =
    useWeatherSummary(
      entityId
    );


  const {
    data: outlook = [],
    isLoading:
      outlookLoading,
    isError:
      outlookError,
  } =
    useWeatherOutlook(
      entityId,
      days
    );


  const {
    data: signals,
    isLoading:
      signalsLoading,
  } =
    useWeatherSignals(
      entityId,
      days
    );


  const formatNumber = (
    value:
      | number
      | null
      | undefined,
    decimals = 1
  ) => {
    if (
      value === null ||
      value === undefined
    ) {
      return "—";
    }

    return value.toFixed(
      decimals
    );
  };


  const formatDate = (
    date: string
  ) => {
    const parsed =
      new Date(date);

    if (
      Number.isNaN(
        parsed.getTime()
      )
    ) {
      return date;
    }

    return parsed.toLocaleDateString(
      "en-GB",
      {
        day: "2-digit",
        month: "short",
      }
    );
  };


  const getDayName = (
    date: string
  ) => {
    const parsed =
      new Date(date);

    if (
      Number.isNaN(
        parsed.getTime()
      )
    ) {
      return "";
    }

    return parsed.toLocaleDateString(
      "en-US",
      {
        weekday: "short",
      }
    );
  };


  const getWeatherIcon = (
    condition:
      | string
      | null
      | undefined
  ) => {
    const text =
      (
        condition ?? ""
      ).toLowerCase();

    if (
      text.includes("rain") ||
      text.includes("shower") ||
      text.includes("drizzle")
    ) {
      return (
        <UmbrellaRounded />
      );
    }

    if (
      text.includes("cloud") ||
      text.includes("overcast")
    ) {
      return (
        <CloudRounded />
      );
    }

    if (
      text.includes("sun") ||
      text.includes("clear")
    ) {
      return (
        <WbSunnyRounded />
      );
    }

    return (
      <CloudRounded />
    );
  };


  const currentTemperature =
    useMemo(() => {
      if (!current) {
        return null;
      }

      return (
        current.tempMax ??
        current.tempMin
      );
    }, [current]);


  const loading =
    currentLoading ||
    outlookLoading ||
    signalsLoading;


  const error =
    currentError ||
    outlookError;


  return (
    <Box
      sx={{
        width: "100%",
        height: "100%",
        bgcolor: "background.paper",
        border: "1px solid",
        borderColor: "divider",
        borderRadius: 12,
        p: { xs: 2.5, md: 4 },
        boxSizing: "border-box",
        overflow: "hidden",
        boxShadow: (t) =>
          t.palette.mode === "dark"
            ? "0 10px 30px rgba(0,0,0,0.4)"
            : "0 10px 30px rgba(16,32,62,0.06)",
      }}
    >
      {/* HEADER */}

      <Stack
        direction="column"
        spacing={3}
        alignItems="flex-start"
        sx={{ minWidth: 0, overflow: "hidden" }}
      >
        <Stack
          direction="row"
          spacing={2}
          alignItems="center"
        >
          <Box
            sx={{
              width: 64,
              height: 64,
              borderRadius: 3,
              bgcolor:
                "#EEF4FF",
              color:
                "#1264FF",
              display: "flex",
              alignItems:
                "center",
              justifyContent:
                "center",
              flexShrink: 0,
            }}
          >
            <CloudRounded
              sx={{
                fontSize: 34,
              }}
            />
          </Box>

          <Box>
            <Typography
              variant="h5"
              fontWeight={800}
              color="text.primary"
            >
              Weather Intelligence
            </Typography>

            <Typography
              color="text.secondary"
              mt={0.5}
            >
              Weather conditions and outlook
              supporting the selected forecast
              for{" "}
              <strong>
                {entityId}
              </strong>
              .
            </Typography>
          </Box>
        </Stack>


        {/* VIEW TOGGLE */}

        <ButtonGroup
          variant="outlined"
          sx={{
            flexShrink: 0,
            "& .MuiButton-root": {
              textTransform:
                "none",
              fontWeight: 700,
              minWidth: {
                xs: 90,
                sm: 105,
              },
            },
          }}
        >
          <Button
            onClick={() =>
              setView("current")
            }
            variant={
              view === "current"
                ? "contained"
                : "outlined"
            }
          >
            Current
          </Button>

          <Button
            onClick={() =>
              setView("7")
            }
            variant={
              view === "7"
                ? "contained"
                : "outlined"
            }
          >
            7 Days
          </Button>

          <Button
            onClick={() =>
              setView("30")
            }
            variant={
              view === "30"
                ? "contained"
                : "outlined"
            }
          >
            30 Days
          </Button>
        </ButtonGroup>
      </Stack>


      <Divider
        sx={{
          my: 3,
        }}
      />


      {/* CURRENT VIEW */}

      {view === "current" && (
        <CurrentWeather
          current={current}
          temperature={
            currentTemperature
          }
          loading={
            currentLoading
          }
          error={
            currentError
          }
          formatNumber={
            formatNumber
          }
          formatDate={
            formatDate
          }
          getWeatherIcon={
            getWeatherIcon
          }
        />
      )}


      {/* OUTLOOK VIEW */}

      {view !== "current" && (
        <>
          {error ? (
            <Typography
              color="error"
              py={4}
            >
              Unable to load the
              weather outlook.
            </Typography>
          ) : loading ? (
            <Typography
              color="text.secondary"
              py={4}
            >
              Loading weather outlook...
            </Typography>
          ) : (
            <>
              <WeatherOutlookGrid
                records={outlook}
                formatNumber={
                  formatNumber
                }
                formatDate={
                  formatDate
                }
                getDayName={
                  getDayName
                }
                getWeatherIcon={
                  getWeatherIcon
                }
              />

              <WeatherSignals
                signals={signals}
                formatNumber={
                  formatNumber
                }
              />
            </>
          )}
        </>
      )}
    </Box>
  );
};


/* =========================================================
   CURRENT WEATHER
========================================================= */


interface CurrentWeatherProps {
  current:
    | {
        condition: string;
        tempMax:
          | number
          | null;
        tempMin:
          | number
          | null;
        rainfall:
          | number
          | null;
        cloudCover:
          | number
          | null;
        humidity:
          | number
          | null;
        windSpeed:
          | number
          | null;
        uvIndex:
          | number
          | null;
        sunshine:
          | number
          | null;
        date: string;
      }
    | null
    | undefined;

  temperature:
    | number
    | null;

  loading: boolean;

  error: boolean;

  formatNumber: (
    value:
      | number
      | null
      | undefined,
    decimals?: number
  ) => string;

  formatDate: (
    value: string
  ) => string;

  getWeatherIcon: (
    condition:
      | string
      | null
      | undefined
  ) => React.ReactNode;
}


const CurrentWeather = ({
  current,
  temperature,
  loading,
  error,
  formatNumber,
  formatDate,
  getWeatherIcon,
}: CurrentWeatherProps) => {
  if (loading) {
    return (
      <Typography color="text.secondary">
        Loading current weather...
      </Typography>
    );
  }

  if (error || !current) {
    return (
      <Typography color="text.secondary">
        No current weather data is
        available for this entity.
      </Typography>
    );
  }


  const items = [
    {
      label: "Condition",
      value:
        current.condition,
      icon:
        getWeatherIcon(
          current.condition
        ),
    },
    {
      label: "High / Low",
      value: `${formatNumber(
        current.tempMax
      )} °C / ${formatNumber(
        current.tempMin
      )} °C`,
      icon:
        <ThermostatRounded />,
    },
    {
      label: "Rainfall",
      value: `${formatNumber(
        current.rainfall
      )} mm`,
      icon:
        <OpacityRounded />,
    },
    {
      label: "Cloud Cover",
      value: `${formatNumber(
        current.cloudCover,
        0
      )}%`,
      icon:
        <CloudRounded />,
    },
    {
      label: "Humidity",
      value: `${formatNumber(
        current.humidity,
        0
      )}%`,
      icon:
        <WaterDropRounded />,
    },
    {
      label: "Wind Speed",
      value: `${formatNumber(
        current.windSpeed
      )} km/h`,
      icon:
        <AirRounded />,
    },
    {
      label: "UV Index",
      value:
        formatNumber(
          current.uvIndex
        ),
      icon:
        <WbSunnyRounded />,
    },
    {
      label: "Sunshine",
      value: `${formatNumber(
        current.sunshine
      )} hrs`,
      icon:
        <WbSunnyRounded />,
    },
  ];


  return (
    <Box>
      <Stack
        direction={{
          xs: "column",
          md: "row",
        }}
        spacing={2}
        justifyContent="space-between"
        mb={3}
      >
        <Box>
          <Typography
            variant="h6"
            fontWeight={800}
            color="text.primary"
          >
            Current Conditions
          </Typography>

          <Typography
            color="text.secondary"
          >
            Latest available observation:
            {" "}
            {formatDate(
              current.date
            )}
          </Typography>
        </Box>

        <Stack
          direction="row"
          spacing={1.5}
          alignItems="center"
        >
          <Box
            sx={{
              px: 2,
              py: 1.25,
              bgcolor:
                "#EEF4FF",
              borderRadius: 2.5,
              color:
                "text.primary",
              fontWeight: 800,
            }}
          >
            {temperature !== null
              ? `${formatNumber(
                  temperature
                )} °C`
              : "—"}
          </Box>

          <Box
            sx={{
              px: 2,
              py: 1.25,
              bgcolor:
                "#F5F6F8",
              borderRadius: 2.5,
              color:
                "#68758A",
              fontWeight: 700,
            }}
          >
            {current.condition}
          </Box>
        </Stack>
      </Stack>


      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs:
              "repeat(1, minmax(0, 1fr))",
            sm:
              "repeat(2, minmax(0, 1fr))",
            lg:
              "repeat(4, minmax(0, 1fr))",
          },
          gap: 2,
        }}
      >
        {items.map(
          (item) => (
            <WeatherMetric
              key={
                item.label
              }
              label={
                item.label
              }
              value={
                item.value
              }
              icon={
                item.icon
              }
            />
          )
        )}
      </Box>
    </Box>
  );
};


/* =========================================================
   WEATHER OUTLOOK
========================================================= */


interface WeatherOutlookGridProps {
  records:
    WeatherOutlookDay[];

  formatNumber: (
    value:
      | number
      | null
      | undefined,
    decimals?: number
  ) => string;

  formatDate: (
    value: string
  ) => string;

  getDayName: (
    value: string
  ) => string;

  getWeatherIcon: (
    condition:
      | string
      | null
      | undefined
  ) => React.ReactNode;
}


const WeatherOutlookGrid = ({
  records,
  formatNumber,
  formatDate,
  getDayName,
  getWeatherIcon,
}: WeatherOutlookGridProps) => {
  if (
    records.length === 0
  ) {
    return (
      <Typography
        color="text.secondary"
        py={4}
      >
        No weather outlook data is
        available.
      </Typography>
    );
  }


  return (
    <Box>
      <Typography
        variant="h6"
        fontWeight={800}
        color="text.primary"
        mb={0.5}
      >
        Weather Outlook
      </Typography>

      <Typography
        color="text.secondary"
        mb={2.5}
      >
        Daily weather conditions available
        to the forecasting pipeline.
      </Typography>


      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs:
              "repeat(1, minmax(0, 1fr))",
            sm:
              "repeat(2, minmax(0, 1fr))",
            md:
              "repeat(3, minmax(0, 1fr))",
            lg:
              records.length > 14
                ? "repeat(5, minmax(0, 1fr))"
                : "repeat(4, minmax(0, 1fr))",
          },
          gap: 1.5,
        }}
      >
        {records.map(
          (
            record: WeatherOutlookDay
          ) => (
            <Box
              key={
                record.date
              }
              sx={{
                p: 2,
                borderRadius: 3,
                bgcolor:
                  "#F7F9FC",
                border:
                  "1px solid #E4E9F0",
                minWidth: 0,
              }}
            >
              <Stack
                direction="row"
                justifyContent="space-between"
                alignItems="center"
                mb={1.5}
              >
                <Box>
                  <Typography
                    fontWeight={800}
                    color="text.primary"
                  >
                    {getDayName(
                      record.date
                    )}
                  </Typography>

                  <Typography
                    variant="caption"
                    color="text.secondary"
                  >
                    {formatDate(
                      record.date
                    )}
                  </Typography>
                </Box>

                <Box
                  sx={{
                    color:
                      "#1264FF",
                  }}
                >
                  {getWeatherIcon(
                    record.condition
                  )}
                </Box>
              </Stack>


              <Typography
                variant="body2"
                fontWeight={700}
                color="#68758A"
                noWrap
                title={
                  record.condition
                }
              >
                {record.condition}
              </Typography>


              <Typography
                variant="h6"
                fontWeight={800}
                color="text.primary"
                mt={1}
              >
                {formatNumber(
                  record.tempMax
                )}°
                <Box
                  component="span"
                  sx={{
                    color:
                      "#8995A7",
                    fontWeight: 600,
                    fontSize:
                      "0.85rem",
                  }}
                >
                  {" "}
                  /{" "}
                  {formatNumber(
                    record.tempMin
                  )}°
                </Box>
              </Typography>


              <Stack
                direction="row"
                spacing={1.5}
                mt={1.5}
                flexWrap="wrap"
                useFlexGap
              >
                <Typography
                  variant="caption"
                  color="#1683D8"
                  fontWeight={700}
                >
                  💧{" "}
                  {formatNumber(
                    record.rainfall
                  )} mm
                </Typography>

                <Typography
                  variant="caption"
                  color="#68758A"
                  fontWeight={700}
                >
                  💨{" "}
                  {formatNumber(
                    record.windSpeed
                  )} km/h
                </Typography>
              </Stack>
            </Box>
          )
        )}
      </Box>
    </Box>
  );
};


/* =========================================================
   WEATHER SIGNALS
========================================================= */


interface WeatherSignalsProps {
  signals:
    | {
        forecastDays: number;
        averageTemperature:
          | number
          | null;
        totalRainfall:
          | number
          | null;
        averageWindSpeed:
          | number
          | null;
        averageUvIndex:
          | number
          | null;
        averageHumidity:
          | number
          | null;
        rainyDays: number;
        hotDays: number;
      }
    | undefined;

  formatNumber: (
    value:
      | number
      | null
      | undefined,
    decimals?: number
  ) => string;
}


const WeatherSignals = ({
  signals,
  formatNumber,
}: WeatherSignalsProps) => {
  if (!signals) {
    return null;
  }


  const items = [
    {
      label:
        "Average temperature",
      value: `${formatNumber(
        signals.averageTemperature
      )} °C`,
      icon:
        <ThermostatRounded />,
      color:
        "#F59E0B",
      bg:
        "#FFF8ED",
    },
    {
      label:
        "Expected rainfall",
      value: `${formatNumber(
